import { useEffect, useRef, useState } from 'react';
import { createBrowserStore } from './services/localStore';
import { clearPdfCache, loadPdf, removePdf, savePdf, type PdfDocument } from './services/pdfLibrary';
import { api, type Account } from './services/api';
import { Activity, AlarmClock, ArrowRight, ArrowUpRight, AudioLines, Bell, BookOpen, CalendarDays, Check, CheckCheck, ChevronDown, ChevronRight, ClipboardCheck, Clock3, Download, Feather, FileText, Flame, Headphones, LayoutDashboard, ListChecks, LoaderCircle, LogOut, Menu, Mic2, MoreHorizontal, Pencil, Plus, Search, Settings2, Sparkles, Target, Trash2, TrendingUp, Trophy, Upload, X } from 'lucide-react';

type Page = 'Overview' | 'Study plan' | 'Weekly roadmap' | 'Progress' | 'Mistake notebook' | 'Mock tests' | 'Study materials' | 'Alerts';
type BeforeInstallPromptEvent = Event & { prompt: () => Promise<void>; userChoice: Promise<{ outcome: 'accepted' | 'dismissed'; platform: string }> };
type Task = { id: number; time: string; duration: number; skill: string; title: string; description: string; done: boolean };
type Mistake = { id: number; skill: string; category: string; title: string; detail: string; date: string };
type Mock = { id: number; date: string; label: string; listening: string; reading: string; writing: string; speaking: string };
type Profile = { name: string; exam: string; target: number; weeks: number; hours: number; level: string; examDate: string };
type State = { profile: Profile; tasks: Task[]; mistakes: Mistake[]; mocks: Mock[]; studyDates: string[]; pdfs: PdfDocument[]; reminderEnabled: boolean; reminderTime: string; reminderStartDate: string; lastReminderDate: string; alertsRead: boolean; currentWeek: number; onboardingDone: boolean };
const dayKey = (date = new Date()) => `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
function studyStreak(dates: string[]) { const recorded = new Set(dates); let cursor = new Date(); if (!recorded.has(dayKey(cursor))) cursor.setDate(cursor.getDate()-1); let count = 0; while (recorded.has(dayKey(cursor))) { count++; cursor.setDate(cursor.getDate()-1); } return count; }
const recentStudyDays = (dates: string[]) => { const set=new Set(dates); let count=0; for(let i=0;i<7;i++){const date=new Date();date.setDate(date.getDate()-i);if(set.has(dayKey(date)))count++;}return count; };
async function showStudyReminder(){const title='A little IELTS practice goes a long way',options={body:'Your study space is ready when you are.',icon:'/icon-192.png'};if('serviceWorker' in navigator&&import.meta.env.PROD){const registration=await navigator.serviceWorker.ready;await registration.showNotification(title,options);}else new Notification(title,options);}
function initialStudyDates() { return Array.from({length:4},(_,i)=>{const date=new Date();date.setDate(date.getDate()-i);return dayKey(date);}); }
const initial: State = {
  profile: { name: 'IELTS learner', exam: 'Academic', target: 8.5, weeks: 12, hours: 4, level: 'Beginner', examDate: '' },
  tasks: [
    { id: 1, time: '09:00', duration: 45, skill: 'Listening', title: 'Map labelling: get your bearings', description: 'Practice predicting directions before the recording starts.', done: true },
    { id: 2, time: '10:00', duration: 60, skill: 'Reading', title: 'True, False, Not Given', description: 'Learn to spot what the passage doesn’t tell you.', done: false },
    { id: 3, time: '11:15', duration: 75, skill: 'Writing', title: 'Task 1: describe a bar chart', description: 'Write a clear overview and compare the key figures.', done: false },
    { id: 4, time: '14:00', duration: 40, skill: 'Speaking', title: 'Part 1: everyday topics', description: 'Build natural, confident answers in 2–3 sentences.', done: false },
    { id: 5, time: '15:00', duration: 20, skill: 'Review', title: 'Review your vocabulary', description: 'Revisit the words you added to your notebook.', done: false },
  ], mistakes: [
    { id: 1, skill: 'Writing', category: 'Grammar', title: 'Subject–verb agreement', detail: 'I wrote “the number of visitors increase.” Remember: “the number” is singular → increases.', date: 'Today' },
    { id: 2, skill: 'Listening', category: 'Spelling', title: 'Double consonants', detail: 'Misspelled “accommodation.” It has two c’s and two m’s.', date: 'Yesterday' },
    { id: 3, skill: 'Reading', category: 'Strategy', title: 'Don’t infer in Not Given', detail: 'A logical conclusion isn’t necessarily stated in the passage.', date: 'Nov 16' },
  ],
  mocks: [
    { id: 1, date: 'Nov 15', label: 'Diagnostic · illustrative', listening: '5.5', reading: '5.0', writing: '5.0', speaking: '5.5' },
  ], studyDates: initialStudyDates(), pdfs: [], reminderEnabled: false, reminderTime: '18:00', reminderStartDate: dayKey(), lastReminderDate: '', alertsRead: false, currentWeek: 1, onboardingDone: false,
};
const store = createBrowserStore<State>('fluent.ielts.v1', initial, value => ({ ...initial, ...value, profile: { ...initial.profile, ...value.profile } }));
const OWNER_KEY = 'fluent.ielts.account.v1';
type SyncStatus = 'saving' | 'saved' | 'offline';
const icons = { Listening: Headphones, Reading: BookOpen, Writing: Feather, Speaking: Mic2, Review: Sparkles } as const;
const skillColors: Record<string, string> = { Listening: '#d08759', Reading: '#6d87ba', Writing: '#977dc2', Speaking: '#589b86', Review: '#bd9a53' };
const goals = [
  { week: 'Week 1', title: 'Build your foundations', sub: 'Get familiar with the format and your baseline.', state: 'current', skills: ['Learn question types', 'Core vocabulary', 'Grammar essentials'] },
  { week: 'Week 2', title: 'Understand the questions', sub: 'Recognize what each question is really asking.', state: 'upcoming', skills: ['Listening: form completion', 'Reading: skimming & scanning', 'Speaking: Part 1'] },
  { week: 'Week 3', title: 'Grow your vocabulary', sub: 'Find the right words and use them with confidence.', state: 'upcoming', skills: ['Topic vocabulary', 'Word families', 'Natural collocations'] },
  { week: 'Week 4', title: 'Write with a clear structure', sub: 'Build paragraphs that answer the question.', state: 'upcoming', skills: ['Task 1 overviews', 'Task 2 planning', 'Linking ideas'] },
  { week: 'Week 5', title: 'Listen for the details', sub: 'Catch distractors, spelling and numbers.', state: 'upcoming', skills: ['Multiple choice', 'Map labelling', 'Listen and predict'] },
  { week: 'Week 6', title: 'Read with a strategy', sub: 'Build speed while keeping your answers accurate.', state: 'upcoming', skills: ['Matching headings', 'True / False / Not Given', 'Time management'] },
  { week: 'Week 7', title: 'Speak more fluently', sub: 'Extend your answers and tell memorable stories.', state: 'upcoming', skills: ['Part 2 cue cards', 'Fluency practice', 'Pronunciation'] },
  { week: 'Week 8', title: 'Make your writing stronger', sub: 'Refine your arguments and describe complex data.', state: 'upcoming', skills: ['Task 2 arguments', 'Charts and diagrams', 'Grammar range'] },
  { week: 'Week 9', title: 'Connect all four skills', sub: 'Put your strengths together in longer practice.', state: 'upcoming', skills: ['Mixed skill sets', 'Speaking Part 3', 'Review weak spots'] },
  { week: 'Week 10', title: 'Practice under time limits', sub: 'Feel at home working against the clock.', state: 'upcoming', skills: ['Timed reading', 'Timed writing', 'Full listening'] },
  { week: 'Week 11', title: 'Take full practice tests', sub: 'Find your finishing touches before test day.', state: 'upcoming', skills: ['Mock test 1', 'Review every error', 'Mock test 2'] },
  { week: 'Week 12', title: 'Walk in with confidence', sub: 'Consolidate what you know and rest well.', state: 'upcoming', skills: ['Final review', 'Light speaking practice', 'Rest and reset'] },
];
const fmtDate = () => new Intl.DateTimeFormat('en', { weekday: 'long', month: 'long', day: 'numeric' }).format(new Date());

function AuthScreen({serverAvailable,initialError,onAuthenticate}:{serverAvailable:boolean;initialError:string;onAuthenticate:(mode:'register'|'login',credentials:{email:string;password:string;displayName:string;importLocal:boolean})=>Promise<void>}) {
  const [mode,setMode]=useState<'login'|'register'>('login');const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [displayName,setDisplayName]=useState('IELTS learner');const [importLocal,setImportLocal]=useState(true);const [error,setError]=useState(initialError);const [busy,setBusy]=useState(false);
  useEffect(()=>setError(initialError),[initialError]);
  const submit=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();setError('');setBusy(true);try{await onAuthenticate(mode,{email,password,displayName,importLocal});}catch(problem){setError(problem instanceof Error?problem.message:'Could not sign in. Please try again.');}finally{setBusy(false);}};
  return <main className="auth-page"><section className="auth-welcome"><a className="brand auth-brand" href="#" onClick={e=>e.preventDefault()}><span className="brand-mark"><AudioLines size={22}/></span><span className="brand-name">fluent<span className="brand-dot">.</span><small>IELTS STUDY SPACE</small></span></a><div className="auth-welcome-copy"><span className="welcome-eyebrow"><span className="live-dot"/> A LITTLE PRACTICE ADDS UP</span><h1>One study plan,<br/><em>wherever you are.</em></h1><p>Pick up your IELTS preparation on your laptop, then keep going on your phone. Your sessions, streaks and practice materials travel with your account.</p><div className="auth-promise-list"><span><Check size={15}/> Your plan stays in sync</span><span><Check size={15}/> Practice PDFs in your library</span><span><Check size={15}/> Your progress, day by day</span></div></div><span className="auth-footer">IELTS Academic · your pace, your goals</span></section><section className="auth-form-side"><div className="auth-form-card"><span className="auth-mobile-mark"><AudioLines size={22}/></span><div className="section-kicker">YOUR PERSONAL IELTS WORKSPACE</div><h2>{mode==='login'?'Welcome back.':'Make your study plan yours.'}</h2><p className="auth-description">{mode==='login'?'Sign in to pick up your study plan on any of your devices.':'Create your account to keep your study plan and files in sync.'}</p><div className="auth-tabs"><button className={mode==='login'?'selected':''} onClick={()=>{setMode('login');setError('')}}>Sign in</button><button className={mode==='register'?'selected':''} onClick={()=>{setMode('register');setError('')}}>Create account</button></div>{error&&<div className={`auth-alert ${!serverAvailable?'auth-alert-offline':''}`}><span>{serverAvailable?'!':'◉'}</span><p>{error}{!serverAvailable&&<small>Check your connection, then reload the page.</small>}</p></div>}<form className="auth-form" onSubmit={submit}>{mode==='register'&&<label>Your name<input autoComplete="name" maxLength={100} value={displayName} onChange={e=>setDisplayName(e.target.value)} required/></label>}<label>Email address<input type="email" autoComplete="email" placeholder="you@example.com" value={email} onChange={e=>setEmail(e.target.value)} required/></label><label>Password<input type="password" autoComplete={mode==='login'?'current-password':'new-password'} minLength={mode==='register'?12:1} maxLength={128} placeholder={mode==='register'?'At least 12 characters':'Enter your password'} value={password} onChange={e=>setPassword(e.target.value)} required/>{mode==='register'&&<small className="auth-field-hint">Use at least 12 characters. Passwords are never stored in your browser.</small>}</label>{mode==='register'&&<label className="sync-consent"><input type="checkbox" checked={importLocal} onChange={e=>setImportLocal(e.target.checked)}/><span>Sync this device’s existing study plan and PDFs to my new account so I can use them on my other devices.</span></label>}<button className="button auth-submit" type="submit" disabled={busy||!serverAvailable}>{busy?<LoaderCircle className="loading-spin" size={16}/>:<>{mode==='login'?'Sign in to your study space':'Create my account'} <ArrowRight size={15}/></>}</button></form><p className="auth-security"><span><Check size={12}/></span>Your sessions are protected by a secure, private account.</p>{!serverAvailable&&!error&&<div className="auth-service-note">Account service is unreachable. Check your connection and reload.</div>}</div></section></main>;
}

export default function App() {
  const [account,setAccount]=useState<Account|null>(null);
  const [accountData,setAccountData]=useState<State>(store.read);
  const [loadingAccount,setLoadingAccount]=useState(true);
  const [serverAvailable,setServerAvailable]=useState(false);
  const [accountError,setAccountError]=useState('');

  useEffect(()=>{let mounted=true;void (async()=>{
    try{
      const user=await api.session();
      if(!mounted)return;
      setServerAvailable(true);
      if(user){
        const [remote,remotePdfs]=await Promise.all([api.getStudyState(),api.listPdfs()]);
        if(!mounted)return;
        const localOwner=window.localStorage.getItem(OWNER_KEY);
        const source=remote.state?remote.state as Partial<State>:localOwner===user.id?store.read():{...initial,profile:{...initial.profile,name:user.display_name}};
        const next={...initial,...source,profile:{...initial.profile,...source.profile},pdfs:remotePdfs};
        setAccountData(next);setAccount(user);store.write(next);window.localStorage.setItem(OWNER_KEY,user.id);
      }
    }catch{if(mounted){setServerAvailable(false);setAccountError('We couldn’t reach your account service. Check your internet connection and try again.');}}
    finally{if(mounted)setLoadingAccount(false);}
  })();return()=>{mounted=false;};},[]);

  const authenticate=async(mode:'register'|'login',credentials:{email:string;password:string;displayName:string;importLocal:boolean})=>{
    const user=mode==='register'?await api.register(credentials.email,credentials.password,credentials.displayName):await api.login(credentials.email,credentials.password);
    const [remote,serverPdfs]=await Promise.all([api.getStudyState(),api.listPdfs()]);
    let next:State;
    if(remote.state){
      const source=remote.state as Partial<State>;
      next={...initial,...source,profile:{...initial.profile,...source.profile},pdfs:serverPdfs};
    }else if(mode==='register'&&credentials.importLocal){
      next={...store.read(),profile:{...store.read().profile,name:store.read().profile.name||credentials.displayName},pdfs:[]};
      for(const localPdf of store.read().pdfs){
        try{const file=await loadPdf(localPdf.id);if(file){const synced=await api.uploadPdf(localPdf.id,file);next.pdfs.push(synced);}}
        catch{next.pdfs.push({...localPdf,cloudSynced:false});}
      }
      await api.saveStudyState({...next,pdfs:next.pdfs.filter(pdf=>pdf.cloudSynced)} as unknown as Record<string,unknown>);
    }else{
      next={...initial,profile:{...initial.profile,name:credentials.displayName||user.display_name},onboardingDone:false,pdfs:[]};
      await api.saveStudyState(next as unknown as Record<string,unknown>);
    }
    setAccountData(next);setAccount(user);setServerAvailable(true);setAccountError('');store.write(next);window.localStorage.setItem(OWNER_KEY,user.id);
  };

  const signOut=async()=>{
    try{await api.logout();}catch{/* Clear local credentials even when the network is unavailable. */}
    store.clear();window.localStorage.removeItem(OWNER_KEY);await clearPdfCache().catch(()=>undefined);setAccount(null);setAccountData(initial);setAccountError('');
  };

  if(loadingAccount)return <div className="account-loading"><span className="brand-mark"><AudioLines size={22}/></span><LoaderCircle className="loading-spin" size={18}/><span>Checking your study account…</span></div>;
  if(!account)return <AuthScreen serverAvailable={serverAvailable} initialError={accountError} onAuthenticate={authenticate}/>;
  return <Workspace key={account.id} initialData={accountData} account={account} onSignOut={signOut}/>;
}

function Workspace({initialData,account,onSignOut}:{initialData:State;account:Account;onSignOut:()=>void}) {
  const [data, setData] = useState<State>(initialData);
  const [page, setPage] = useState<Page>('Overview');
  const [modal, setModal] = useState<'profile' | 'mistake' | 'mock' | 'diagnostic' | 'task' | null>(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [toast, setToast] = useState('');
  const [expandedWeek, setExpandedWeek] = useState(1);
  const [skillFilter, setSkillFilter] = useState('All skills');
  const [profileForm, setProfileForm] = useState<Profile>(data.profile);
  const [search, setSearch] = useState('');
  const [pdfViewer, setPdfViewer] = useState<{ name: string; url: string } | null>(null);
  const [installPrompt, setInstallPrompt] = useState<BeforeInstallPromptEvent | null>(null);
  const syncQueue=useRef<Promise<void>>(Promise.resolve());
  const [syncStatus,setSyncStatus]=useState<SyncStatus>('saved');
  useEffect(() => {store.write(data);window.localStorage.setItem(OWNER_KEY,account.id);}, [data,account.id]);
  useEffect(()=>{let mounted=true;const timer=window.setTimeout(()=>{setSyncStatus('saving');const cloudState={...data,pdfs:data.pdfs.filter(pdf=>pdf.cloudSynced)} as unknown as Record<string,unknown>;syncQueue.current=syncQueue.current.catch(()=>undefined).then(()=>api.saveStudyState(cloudState).then(()=>{if(mounted)setSyncStatus('saved');}).catch(()=>{if(mounted){setSyncStatus('offline');setToast('Saved on this device. Cloud sync will retry when you are connected.');}}));},900);return()=>{mounted=false;window.clearTimeout(timer);};},[data,account.id]);
  useEffect(() => { if (!data.onboardingDone) setModal('profile'); }, []);
  useEffect(() => { const handler=(event:Event)=>{event.preventDefault();setInstallPrompt(event as BeforeInstallPromptEvent)};window.addEventListener('beforeinstallprompt',handler);return()=>window.removeEventListener('beforeinstallprompt',handler); }, []);
  useEffect(() => {
    if (!data.reminderEnabled) return;
    const checkReminder = () => {
      const now=new Date(), today=dayKey(now), time=`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;
      if(time<data.reminderTime||today<data.reminderStartDate||data.lastReminderDate===today)return;
      if('Notification' in window&&Notification.permission==='granted')void showStudyReminder().catch(()=>setToast('It’s time to study. Your plan is waiting in Fluent.'));
      change(s=>({...s,lastReminderDate:today}));
    };
    checkReminder();const timer=window.setInterval(checkReminder,30000);return()=>window.clearInterval(timer);
  },[data.reminderEnabled,data.reminderTime,data.reminderStartDate,data.lastReminderDate]);
  useEffect(() => { if (toast) { const t = setTimeout(() => setToast(''), 2500); return () => clearTimeout(t); } }, [toast]);
  const finished = data.tasks.filter(t => t.done).length;
  const minsDone = data.tasks.filter(t => t.done).reduce((a, t) => a + t.duration, 0);
  const percent = Math.round(finished / Math.max(data.tasks.length, 1) * 100);
  const change = (fn: (s: State) => State) => setData(s => fn(s));
  const navigate = (p: Page) => { setPage(p); setSidebarOpen(false); if(p==='Alerts')change(s=>({...s,alertsRead:true})); };
  const toggleTask = (id: number) => change(s => { const task=s.tasks.find(t=>t.id===id);const nowCompleting=task&&!task.done;const today=dayKey();return { ...s,alertsRead:false, studyDates:nowCompleting?[...new Set([...s.studyDates,today])]:s.studyDates, tasks: s.tasks.map(t => t.id === id ? { ...t, done: !t.done } : t) }; });
  const addTask = (title: string, skill: string, duration: number) => { change(s => ({ ...s, tasks: [...s.tasks, { id: Date.now(), time: '16:00', duration, skill, title, description: 'A new session added to your personal study plan.', done: false }] })); setModal(null); setToast('Study session added'); };
  const updateProfile = (e: React.FormEvent) => { e.preventDefault(); change(s => ({ ...s, profile: profileForm, onboardingDone: true })); setModal(null); setToast('Your study profile is up to date'); };
  const createMistake = (e: React.FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); change(s => ({ ...s, mistakes: [{ id: Date.now(), skill: String(f.get('skill')), category: String(f.get('category')), title: String(f.get('title')), detail: String(f.get('detail')), date: 'Today' }, ...s.mistakes] })); setModal(null); setToast('Added to your mistake notebook'); };
  const createMock = (e: React.FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); change(s => ({ ...s, mocks: [{ id: Date.now(), date: String(f.get('date')), label: String(f.get('label')), listening: String(f.get('listening')), reading: String(f.get('reading')), writing: String(f.get('writing')), speaking: String(f.get('speaking')) }, ...s.mocks] })); setModal(null); setToast('Practice test saved'); };
  const enableReminders = async () => { if(!('Notification' in window)){setToast('This browser does not support system notifications.');return;}const permission=Notification.permission==='granted'?'granted':await Notification.requestPermission();if(permission==='granted'){const now=new Date(),current=`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;let start=now;if(current>data.reminderTime)start.setDate(start.getDate()+1);change(s=>({...s,reminderEnabled:true,reminderStartDate:dayKey(start),alertsRead:true}));setToast(`Daily reminder set for ${data.reminderTime}. Keep Fluent open.`);}else setToast('Notifications are off. You can enable them in your browser settings.'); };
  const removeStudyPdf = async (pdf:PdfDocument) => {if(!window.confirm(`Remove “${pdf.name}” from your account and devices?`))return;try{if(pdf.cloudSynced)await api.deletePdf(pdf.id);await removePdf(pdf.id);change(s=>({...s,pdfs:s.pdfs.filter(item=>item.id!==pdf.id)}));setToast('PDF removed from your library and devices.');}catch{setToast('Could not remove this PDF. Check your connection and try again.');}};
  const syncStudyPdf = async (pdf:PdfDocument) => {try{const file=await loadPdf(pdf.id);if(!file){setToast('This PDF is missing from this device. Open it to download your account copy.');return;}const synced=await api.uploadPdf(pdf.id,file);change(s=>({...s,pdfs:s.pdfs.map(item=>item.id===pdf.id?synced:item)}));setToast('PDF synced to your account and other devices.');}catch{setToast('Could not sync this PDF. Check your connection and try again.');}};
  const addPdfs = async (files: FileList | File[]) => {const chosen=Array.from(files);if(!chosen.length)return;for(const file of chosen){if(file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf')){setToast(`${file.name} is not a PDF.`);continue;}if(file.size>25*1024*1024){setToast(`${file.name} exceeds the 25 MB limit.`);continue;}try{let saved=await savePdf(file);let synced=false;try{saved=await api.uploadPdf(saved.id,file);synced=true;}catch{/* Keep the device copy and let the learner retry the cloud upload later. */}change(s=>({...s,pdfs:[{...saved,cloudSynced:synced},...s.pdfs],alertsRead:false}));setToast(synced?`${file.name} added and synced to your account.`:`${file.name} saved on this device. Cloud upload will retry when available.`);}catch{setToast('Could not save this PDF. Check your device storage and try again.');}}};
  const openPdf = async (pdf: PdfDocument) => {try{let file=await loadPdf(pdf.id).catch(()=>null);if(!file&&account)file=await api.fetchPdf(pdf.id);if(!file){setToast('This PDF is unavailable. Please add it again.');return;}if(!await loadPdf(pdf.id).catch(()=>null))await savePdf(file,pdf.id);setPdfViewer({name:file.name,url:URL.createObjectURL(file)});}catch{setToast('Could not open this PDF. Check your internet connection and try again.');}};
  const installApp = async () => { if(!installPrompt)return;await installPrompt.prompt();const result=await installPrompt.userChoice;if(result.outcome==='accepted')setInstallPrompt(null); };

  return <div className="app-shell">
    <aside className={`sidebar ${sidebarOpen ? 'sidebar-open' : ''}`}>
      <a className="brand" href="#" onClick={e => {e.preventDefault();navigate('Overview')}}><span className="brand-mark"><AudioLines size={22}/></span><span className="brand-name">fluent<span className="brand-dot">.</span><small>IELTS STUDY SPACE</small></span></a>
      <div className="nav-caption">YOUR WORKSPACE</div>
      <nav className="primary-nav">{([['Overview',LayoutDashboard],['Study plan',CalendarDays],['Weekly roadmap',Target],['Progress',TrendingUp],['Mistake notebook',BookOpen],['Mock tests',ClipboardCheck],['Study materials',FileText],['Alerts',Bell]] as const).map(([label,Icon])=><button key={label} onClick={()=>navigate(label)} className={`nav-item ${page===label?'active':''}`}><Icon size={18} strokeWidth={1.8}/><span>{label}</span>{label==='Mistake notebook'&&<span className="nav-count">{data.mistakes.length}</span>}{label==='Mock tests'&&<span className="nav-count">{data.mocks.length}</span>}{label==='Study materials'&&data.pdfs.length>0&&<span className="nav-count">{data.pdfs.length}</span>}{label==='Alerts'&&!data.alertsRead&&<span className="unread-dot"/>}</button>)}</nav>
      <div className="sidebar-spacer"/>
      <button className="streak-card" onClick={()=>navigate('Alerts')} aria-label="View your study streak and alerts"><div className="streak-icon"><Flame size={18}/></div><div><strong>{studyStreak(data.studyDates)} day streak</strong><span>{studyStreak(data.studyDates)>0?'Your practice is adding up.':'One session starts a streak.'}</span></div><ArrowUpRight size={15} className="streak-arrow"/></button>
      <button className="profile-button" onClick={()=>{setProfileForm(data.profile);setModal('profile')}}><span className="avatar">{data.profile.name.split(' ').map(n=>n[0]).join('').slice(0,2)}</span><span className="profile-copy"><strong>{data.profile.name}</strong><small>{data.profile.level} learner</small></span><MoreHorizontal size={19} className="muted-icon"/></button>
      <button className="sidebar-settings" onClick={()=>{setProfileForm(data.profile);setModal('profile')}}><Settings2 size={16}/> Study preferences <ArrowRight size={14} className="settings-arrow"/></button><button className="sidebar-settings signout-link" onClick={onSignOut}><LogOut size={16}/> Sign out</button>
    </aside>
    {sidebarOpen&&<button className="mobile-scrim" aria-label="Close menu" onClick={()=>setSidebarOpen(false)}/>}
    <main className="main-area">
      <header className="topbar"><button className="mobile-menu icon-button" onClick={()=>setSidebarOpen(true)} aria-label="Open navigation"><Menu size={20}/></button><div className="breadcrumb">My workspace <ChevronRight size={14}/><strong>{page}</strong></div><div className="topbar-right"><span className={`sync-badge sync-${syncStatus}`}><i/>{syncStatus==='saving'?'Syncing':syncStatus==='offline'?'Saved on this device':'Synced'}</span><span className="date-label"><CalendarDays size={15}/>{fmtDate()}</span><button className="icon-button notification-button" aria-label={data.alertsRead?'View alerts':'View alerts, unread'} onClick={()=>navigate('Alerts')}><Bell size={18}/>{!data.alertsRead&&<span className="notification-dot"/>}</button><span className="top-avatar">{data.profile.name.split(' ').map(n=>n[0]).join('').slice(0,2)}</span></div></header>
      <div className="page-content">{page==='Overview'?<Overview data={data} finished={finished} percent={percent} minsDone={minsDone} onToggle={toggleTask} onNavigate={navigate} onAdd={()=>setModal('task')} onProfile={()=>{setProfileForm(data.profile);setModal('profile')}} onAddMock={()=>setModal('mock')}/>:page==='Study plan'?<StudyPlan data={data} filter={skillFilter} setFilter={setSkillFilter} onToggle={toggleTask} onAdd={()=>setModal('task')}/>:page==='Weekly roadmap'?<Roadmap currentWeek={data.currentWeek} expanded={expandedWeek} setExpanded={setExpandedWeek} onDiagnostic={()=>setModal('diagnostic')}/>:page==='Progress'?<Progress data={data} finished={finished} onAddMock={()=>setModal('mock')} onNavigate={navigate}/>:page==='Mistake notebook'?<MistakeNotebook mistakes={data.mistakes} search={search} setSearch={setSearch} onAdd={()=>setModal('mistake')}/>:page==='Mock tests'?<MockTests mocks={data.mocks} onAdd={()=>setModal('mock')}/>:page==='Study materials'?<StudyMaterials pdfs={data.pdfs} onUpload={addPdfs} onOpen={openPdf} onRemove={removeStudyPdf} onRetrySync={syncStudyPdf} onInstall={installApp} canInstall={!!installPrompt}/>:<Alerts data={data} streak={studyStreak(data.studyDates)} installPrompt={!!installPrompt} onTime={(time)=>{const now=new Date(),current=`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;let start=now;if(current>time)start.setDate(start.getDate()+1);change(s=>({...s,reminderTime:time,reminderStartDate:dayKey(start)}));}} onToggleReminder={(enabled)=>enabled?void enableReminders():(change(s=>({...s,reminderEnabled:false})),setToast('Daily reminder paused.'))} onInstall={installApp}/>}</div>
      <footer className="footer"><span>Made for steady progress.</span><span><span className="illustrative-dot"/> Starter scores and study data are illustrative</span></footer>
    </main>
    {modal&&<Modal modal={modal} isOnboarding={!data.onboardingDone} profile={profileForm} setProfile={setProfileForm} onClose={()=>setModal(null)} onSaveProfile={updateProfile} onAddMistake={createMistake} onAddMock={createMock} onAddTask={addTask} onDiagnostic={(skill)=>{change(s=>({...s,mocks:[{id:Date.now(),date:new Intl.DateTimeFormat('en',{month:'short',day:'numeric'}).format(new Date()),label:`Diagnostic · ${skill}`,listening:'—',reading:'—',writing:'—',speaking:'—'},...s.mocks]}));setModal(null);navigate('Mock tests');setToast(`Diagnostic started. Add your ${skill.toLowerCase()} result when you finish.`)}}/>}
    {pdfViewer&&<div className="pdf-viewer-overlay"><header className="pdf-viewer-top"><button className="icon-button" onClick={()=>{URL.revokeObjectURL(pdfViewer.url);setPdfViewer(null)}} aria-label="Close PDF"><X size={19}/></button><strong title={pdfViewer.name}>{pdfViewer.name}</strong><a className="button" href={pdfViewer.url} download={pdfViewer.name}><Download size={16}/> Download PDF</a></header><iframe title={pdfViewer.name} src={pdfViewer.url}/><p>On iPhone or iPad: use your browser’s Share menu and choose <strong>Save to Files</strong> if the PDF opens instead of downloading.</p></div>}
    {toast&&<div className="toast"><CheckCircle/>{toast}</div>}
  </div>;
}
function CheckCircle(){return <span className="toast-check"><Check size={15}/></span>}

function Heading({eyebrow,title,sub,right}:{eyebrow:string;title:React.ReactNode;sub:string;right?:React.ReactNode}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{sub}</p></div>{right&&<div className="heading-actions">{right}</div>}</div>}
function Button({children,onClick,variant='primary',icon}:{children:React.ReactNode;onClick?:()=>void;variant?:'primary'|'secondary'|'quiet'|'light';icon?:React.ReactNode}){return <button className={`button button-${variant}`} onClick={onClick}>{icon}{children}</button>}
function Overview({data,finished,percent,minsDone,onToggle,onNavigate,onAdd,onProfile,onAddMock}:{data:State;finished:number;percent:number;minsDone:number;onToggle:(id:number)=>void;onNavigate:(p:Page)=>void;onAdd:()=>void;onProfile:()=>void;onAddMock:()=>void}){
  const upcoming=goals[Math.min(data.currentWeek-1,11)];
  const weekDays=recentStudyDays(data.studyDates);
  return <><Heading eyebrow="THURSDAY, YOUR NEXT CHAPTER" title={<>A little progress goes <em>a long way.</em></>} sub={`Good to see you, ${data.profile.name === 'IELTS learner' ? 'there' : data.profile.name.split(' ')[0]}. Your IELTS journey starts with today.`} right={<Button variant="secondary" icon={<Pencil size={15}/>} onClick={onProfile}>Your study profile</Button>}/>
    <section className="welcome-banner"><div className="welcome-copy"><div className="welcome-eyebrow"><span className="live-dot"/> YOUR PERSONAL STUDY PLAN</div><h2>From beginner to band <span>{data.profile.target.toFixed(1)}</span>.</h2><p>Twelve weeks, four focused hours a day, one skill at a time.<br className="desktop-only"/> We’ve got a plan that moves at your pace.</p><div className="welcome-bottom"><div className="plan-meta"><span><Target size={14}/> IELTS {data.profile.exam}</span><span className="meta-divider"/><span><CalendarDays size={14}/> {data.profile.examDate?new Intl.DateTimeFormat('en',{month:'short',day:'numeric',year:'numeric'}).format(new Date(`${data.profile.examDate}T00:00:00`)):'Exam date not set'}</span></div><Button variant="light" onClick={()=>onNavigate('Weekly roadmap')}>Explore your roadmap <ArrowRight size={15}/></Button></div></div><div className="welcome-art" aria-hidden="true"><div className="orb orb-back"/><div className="orb orb-front"><div className="orb-inner"><AudioLines size={49}/><span>YOUR<br/>NEXT STEP</span></div></div><span className="sparkle sparkle-one">✳</span><span className="sparkle sparkle-two">✦</span><span className="orbit orbit-one"/><span className="orbit orbit-two"/></div></section>
    <section className="stats-grid"><StatCard icon={<ListChecks size={18}/>} color="sage" label="TODAY’S FOCUS" value={`${finished} of ${data.tasks.length}`} unit="sessions" note="one small win at a time"/><StatCard icon={<Clock3 size={18}/>} color="blue" label="TIME WELL SPENT" value={`${minsDone} min`} unit="today" note="of your 4-hour daily goal"/><StatCard icon={<TrendingUp size={18}/>} color="lavender" label="PLAN CHECK-IN" value={`${percent}%`} unit="complete" note="you’re building momentum"/><StatCard icon={<Trophy size={18}/>} color="peach" label="YOUR TARGET" value={data.profile.target.toFixed(1)} unit="band" note={`${data.profile.weeks} weeks to get there`}/></section>
    <div className="dashboard-grid"><section className="card today-card"><div className="section-head"><div><div className="section-kicker">YOUR DAY, AT A GLANCE</div><h3>Today’s study plan <span className="pill-date">{fmtDate().split(',')[0]}</span></h3></div><button className="text-link" onClick={()=>onNavigate('Study plan')}>Full schedule <ArrowRight size={14}/></button></div><div className="task-list">{data.tasks.slice(0,5).map(task=><TaskRow key={task.id} task={task} onToggle={()=>onToggle(task.id)}/>)}</div><div className="plan-card-bottom"><div className="completion-copy"><div className="completion-track"><span style={{width:`${percent}%`}}/></div><span>{finished} of {data.tasks.length} sessions done <b>·</b> {data.tasks.length-finished} to go</span></div><button className="icon-button add-task-button" onClick={onAdd} aria-label="Add a study session"><Plus size={18}/></button></div></section>
    <aside className="right-column"><section className="card week-card"><div className="section-head"><div><div className="section-kicker">YOUR BIG PICTURE</div><h3>This week</h3></div><button className="round-link" aria-label="View weekly roadmap" onClick={()=>onNavigate('Weekly roadmap')}><ArrowUpRight size={17}/></button></div><div className="week-progress"><span className="week-progress-ring" style={{'--progress':`${weekDays/7*100}%`} as React.CSSProperties}><span>{weekDays}<small> / 7</small></span></span><div><div className="week-progress-title">Little wins add up</div><div className="week-progress-sub">You’ve practiced {weekDays} days this week. Keep showing up.</div></div></div><div className="week-goal"><span className="week-goal-icon"><Sparkles size={15}/></span><span><small>THIS WEEK’S INTENTION</small><strong>{upcoming.title}</strong></span><button onClick={()=>onNavigate('Weekly roadmap')} aria-label="View roadmap"><ArrowRight size={15}/></button></div></section>
      <section className="card skills-card"><div className="section-head"><div><div className="section-kicker">A WELL-ROUNDED APPROACH</div><h3>Four skills, one goal</h3></div><button className="text-link" onClick={()=>onNavigate('Progress')}>Progress <ArrowRight size={14}/></button></div><SkillRow name="Listening" current="5.5" color="orange"/><SkillRow name="Reading" current="5.0" color="blue"/><SkillRow name="Writing" current="5.0" color="purple"/><SkillRow name="Speaking" current="5.5" color="green"/><div className="illustrative-note"><span className="illustrative-dot"/> Illustrative starting point · add your diagnostic scores</div></section>
    </aside></div>
    <section className="next-step-card"><div className="next-step-icon"><Sparkles size={21}/></div><div className="next-step-copy"><div className="section-kicker">YOUR FIRST MILESTONE</div><strong>Start with a quick skills check</strong><p>Get a starting point for all four skills so your plan can grow with you.</p></div><div className="next-step-actions"><Button variant="secondary" icon={<ClipboardCheck size={15}/>} onClick={onAddMock}>Log a mock test</Button><Button icon={<ArrowRight size={15}/>} onClick={()=>onNavigate('Weekly roadmap')}>See week 1</Button></div></section>
  </>;
}
function StatCard({icon,color,label,value,unit,note}:{icon:React.ReactNode;color:string;label:string;value:string;unit:string;note:string}){return <article className="stat-card"><div className="stat-top"><span className={`stat-icon ${color}`}>{icon}</span><span className="stat-label">{label}</span></div><div className="stat-value">{value}<span> {unit}</span></div><div className="stat-note"><span className="stat-indicator"/>{note}</div></article>}
function TaskRow({task,onToggle}:{task:Task;onToggle:()=>void}){const Icon=icons[task.skill as keyof typeof icons]||Sparkles;return <div className={`task-row ${task.done?'task-done':''}`}><span className="task-time">{task.time}</span><button className={`task-check ${task.done?'checked':''}`} onClick={onToggle} aria-label={task.done?'Mark incomplete':'Mark complete'}>{task.done?<Check size={13}/>:null}</button><span className="task-skill-icon" style={{'--skill-color':skillColors[task.skill]||skillColors.Review} as React.CSSProperties}><Icon size={16}/></span><div className="task-content"><div className="task-title">{task.title}</div><div className="task-description">{task.description}</div></div><span className="task-duration"><Clock3 size={12}/>{task.duration}m</span></div>}
function SkillRow({name,current,color}:{name:string;current:string;color:string}){const values:Record<string,number>={'5.0':5,'5.5':5.5,'6.0':6,'6.5':6.5,'7.0':7,'7.5':7.5,'8.0':8,'8.5':8.5};return <div className="skill-row"><span className={`skill-dot ${color}`}/><span className="skill-name">{name}</span><div className="skill-track"><span className={color} style={{width:`${(values[current]||5)/9*100}%`}}/></div><span className="skill-score">{current}</span></div>}

function StudyPlan({data,filter,setFilter,onToggle,onAdd}:{data:State;filter:string;setFilter:(f:string)=>void;onToggle:(id:number)=>void;onAdd:()=>void}){const skills=['All skills','Listening','Reading','Writing','Speaking','Review'];const tasks=data.tasks.filter(t=>filter==='All skills'||t.skill===filter);return <><Heading eyebrow="YOUR DAILY RHYTHM" title={<>A plan that fits <em>your day.</em></>} sub="Build a routine that feels doable. Every completed session moves you forward." right={<Button icon={<Plus size={16}/>} onClick={onAdd}>Add a session</Button>}/><div className="schedule-summary"><div className="schedule-summary-icon"><CalendarDays size={20}/></div><div><strong>{fmtDate()}</strong><span>{data.tasks.filter(t=>!t.done).length} sessions to go · just take them one at a time</span></div><div className="schedule-hours"><strong>{data.tasks.reduce((a,t)=>a+t.duration,0)}<small> min</small></strong><span>planned today</span></div></div><div className="filter-row">{skills.map(s=><button className={`filter-chip ${filter===s?'selected':''}`} key={s} onClick={()=>setFilter(s)}>{s}</button>)}</div><div className="card schedule-card"><div className="section-head"><div><div className="section-kicker">YOUR SESSION LIST</div><h3>Today’s focus <span className="soft-count">{tasks.length}</span></h3></div><span className="plan-status"><span/> Plan in progress</span></div><div className="task-list">{tasks.map(task=><TaskRow key={task.id} task={task} onToggle={()=>onToggle(task.id)}/>)}</div>{tasks.length===0&&<div className="empty-filter">No sessions for {filter} yet. Add one when you’re ready.</div>}<div className="schedule-footer"><div className="schedule-hint"><Sparkles size={15}/> Consistency matters more than perfection.</div><Button variant="secondary" icon={<Plus size={15}/>} onClick={onAdd}>Add a study session</Button></div></div><div className="gentle-note"><span className="gentle-note-icon"><Activity size={17}/></span><p><strong>A gentle reminder:</strong> This is your plan, not a test. Edit, move or skip sessions whenever you need to. The best study routine is one that works for you.</p></div></>}

function Roadmap({currentWeek,expanded,setExpanded,onDiagnostic}:{currentWeek:number;expanded:number;setExpanded:(n:number)=>void;onDiagnostic:()=>void}){return <><Heading eyebrow="12 WEEKS, ONE STEP AT A TIME" title={<>Your path to band <em>8.5.</em></>} sub="A practical, beginner-friendly roadmap. Each week lays a new brick; your pace is the right pace." right={<span className="roadmap-badge"><Target size={15}/> 12-week journey</span>}/><div className="roadmap-banner"><div className="roadmap-banner-icon"><Target size={22}/></div><div><strong>Every expert started somewhere.</strong><span>This plan begins with the basics and gradually builds all four IELTS skills.</span></div><button className="banner-action" onClick={onDiagnostic}>Take your starting-point check <ArrowRight size={15}/></button></div><div className="roadmap-layout"><div className="timeline">{goals.map((g,i)=>{const weekNo=i+1;const done=weekNo<currentWeek;const open=expanded===weekNo;return <div className={`timeline-item ${done?'timeline-done':''} ${open?'timeline-open':''}`} key={g.week}><div className="timeline-rail"><span className="timeline-dot">{done?<Check size={13}/>:String(weekNo).padStart(2,'0')}</span>{i<11&&<span className="timeline-line"/>}</div><div className="timeline-card"><button className="timeline-card-head" onClick={()=>setExpanded(open?0:weekNo)}><span className="timeline-title-wrap"><span className="timeline-week">{g.week.toUpperCase()}{weekNo===currentWeek&&<span className="current-badge">YOU ARE HERE</span>}</span><strong>{g.title}</strong><span className="timeline-sub">{g.sub}</span></span><ChevronDown size={18} className={open?'rotate-chevron':''}/></button>{open&&<div className="timeline-details"><div className="milestone-list">{g.skills.map((s,j)=><div className="milestone-item" key={s}><span className="milestone-number">0{j+1}</span>{s}</div>)}</div><div className="week-footnote"><Clock3 size={13}/> Suggested focus: 4 hours daily across the four skills</div></div>}</div></div>})}</div><aside className="roadmap-aside"><div className="card roadmap-note"><div className="roadmap-note-icon"><Sparkles size={18}/></div><div className="section-kicker">A NOTE FOR YOUR JOURNEY</div><h3>Progress, at your own pace.</h3><p>This roadmap is a starting point, not a deadline. Adjust the weeks and sessions as you learn more about yourself.</p><div className="note-divider"/><div className="pace-stat"><span><CheckCheck size={16}/></span><div><strong>{currentWeek} of 12 weeks</strong><small>You’re on the first step.</small></div></div></div><div className="roadmap-tip"><span><Sparkles size={15}/></span><div><strong>Start with a diagnostic</strong><p>Knowing where you are helps you decide what to work on next.</p><button onClick={onDiagnostic}>Add your starting point <ArrowRight size={13}/></button></div></div></aside></div></>}

function Progress({data,finished,onAddMock,onNavigate}:{data:State;finished:number;onAddMock:()=>void;onNavigate:(p:Page)=>void}){const skills=['Listening','Reading','Writing','Speaking'];const skillcolors=['orange','blue','purple','green'];return <><Heading eyebrow="NOTICE HOW FAR YOU’VE COME" title={<>Small steps. <em>Real progress.</em></>} sub="Your scores are starting points, not limits. Update them whenever you complete practice." right={<Button icon={<Plus size={16}/>} onClick={onAddMock}>Log practice results</Button>}/><div className="progress-hero"><div className="progress-hero-icon"><TrendingUp size={21}/></div><div><div className="section-kicker">A LOOK AT YOUR JOURNEY</div><strong>{data.studyDates.length} days showing up</strong><span>You’ve completed {finished} sessions today. That’s something to feel good about.</span></div><button className="progress-week" onClick={()=>onNavigate('Weekly roadmap')}><span>WEEK</span><strong>{data.currentWeek}<small> / 12</small></strong><ArrowUpRight size={15}/></button></div><div className="progress-grid">{skills.map((skill,i)=>{const tests=data.mocks.filter(m=>m[skill.toLowerCase() as keyof Mock]!=='—');const score=tests.length?tests[0][skill.toLowerCase() as keyof Mock] as string:'—';return <section className="card progress-skill-card" key={skill}><div className="progress-skill-top"><span className={`progress-skill-icon ${skillcolors[i]}`}>{[<Headphones size={19}/>,<BookOpen size={19}/>,<Feather size={19}/>,<Mic2 size={19}/>][i]}</span><span className="score-starter">{tests.length?(tests[0].label.toLowerCase().includes('illustrative')?'ILLUSTRATIVE START':'LATEST SCORE'):'AWAITING YOUR CHECK-IN'}</span></div><div className="progress-skill-name">{skill}</div><div className="progress-score">{score}<small>{score==='—'?'Add your first score':' / 9.0'}</small></div><div className="band-track"><span className={skillcolors[i]} style={{width:`${score==='—'?0:Number(score)/9*100}%`}}/></div><div className="band-track-labels"><span>0</span><span>4.5</span><span>9</span></div><button className="progress-card-link" onClick={onAddMock}>{tests.length?'Update score':'Add score'} <ArrowRight size={13}/></button></section>})}</div><div className="card progress-history"><div className="section-head"><div><div className="section-kicker">PRACTICE THAT ADDS UP</div><h3>Recent practice</h3></div><button className="text-link" onClick={()=>onNavigate('Mock tests')}>All results <ArrowRight size={14}/></button></div>{data.mocks.length?<div className="mini-results">{data.mocks.slice(0,3).map(mock=><div className="mini-result" key={mock.id}><span className="mini-result-icon"><ClipboardCheck size={17}/></span><span className="mini-result-name"><strong>{mock.label}</strong><small>{mock.date} · illustrative starter data</small></span><span className="mini-score-wrap">{(['listening','reading','writing','speaking'] as const).map((s,i)=><span key={s} className="mini-score"><small>{['L','R','W','S'][i]}</small>{mock[s]}</span>)}</span></div>)}</div>:<div className="empty-state"><span className="empty-state-icon"><TrendingUp size={21}/></span><strong>Your progress starts with one check-in.</strong><p>Log a diagnostic or practice test to see your four-skill journey take shape.</p><Button variant="secondary" onClick={onAddMock} icon={<Plus size={15}/>}>Log your first result</Button></div>}</div></>}

function MistakeNotebook({mistakes,search,setSearch,onAdd}:{mistakes:Mistake[];search:string;setSearch:(s:string)=>void;onAdd:()=>void}){const [filter,setFilter]=useState('All skills');const shown=mistakes.filter(m=>(filter==='All skills'||m.skill===filter)&&`${m.skill} ${m.category} ${m.title} ${m.detail}`.toLowerCase().includes(search.toLowerCase()));return <><Heading eyebrow="YOUR LEARNING JOURNAL" title={<>Turn every slip into <em>a step forward.</em></>} sub="A kind, private place to catch patterns and remember what you’ve learned." right={<Button icon={<Plus size={16}/>} onClick={onAdd}>Add a note</Button>}/><div className="notebook-callout"><span className="notebook-illustration"><BookOpen size={24}/><Sparkles size={13}/></span><div><strong>Mistakes mean you’re learning.</strong><span>Write down what tripped you up and what you’ll try next time. That’s how confidence grows.</span></div><div className="notebook-count"><strong>{mistakes.length}</strong><small>learning moments</small></div></div><div className="notebook-toolbar"><div className="notebook-filters">{['All skills','Listening','Reading','Writing','Speaking'].map(f=><button key={f} className={`filter-chip ${filter===f?'selected':''}`} onClick={()=>setFilter(f)}>{f}</button>)}</div><label className="search-field"><Search size={15}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search your notes…"/><kbd>⌘ K</kbd></label></div><div className="mistake-list">{shown.map(m=><article className="card mistake-card" key={m.id}><div className="mistake-color-bar" style={{background:skillColors[m.skill]||'#9bb08e'}}/><div className="mistake-card-inner"><div className="mistake-card-meta"><span className="mistake-skill-pill" style={{'--skill-color':skillColors[m.skill]||'#9bb08e'} as React.CSSProperties}>{m.skill}</span><span className="mistake-category">{m.category}</span><span className="mistake-date">{m.date}</span><button className="mistake-more" onClick={()=>navigator.clipboard?.writeText(m.detail).then(()=>{})} aria-label="Copy note"><MoreHorizontal size={18}/></button></div><h3>{m.title}</h3><p>{m.detail}</p><div className="mistake-takeaway"><span><Sparkles size={14}/></span><div><small>THE TAKEAWAY</small><span>{m.category==='Spelling'?'Add this word to your vocabulary review.':m.category==='Strategy'?'Pause and check what the passage actually says.':'Look for this pattern in your next practice.'}</span></div></div></div></article>)}{shown.length===0&&<div className="empty-state card"><span className="empty-state-icon"><Search size={20}/></span><strong>No notes found.</strong><p>Try a different search, or add a new learning moment.</p><Button onClick={onAdd} icon={<Plus size={15}/>}>Add your first note</Button></div>}</div><div className="notebook-footer"><span><span className="illustrative-dot"/> Starter notes are illustrative examples you can edit or remove.</span><button onClick={onAdd}>Add a learning moment <ArrowRight size={14}/></button></div></>}

function MockTests({mocks,onAdd}:{mocks:Mock[];onAdd:()=>void}){return <><Heading eyebrow="PRACTICE MAKES PROGRESS" title={<>Practice today. <em>Confident tomorrow.</em></>} sub="Keep a record of your full tests, partial tests and diagnostic check-ins." right={<Button icon={<Plus size={16}/>} onClick={onAdd}>Log a practice test</Button>}/><div className="mock-banner"><div className="mock-banner-icon"><ClipboardCheck size={21}/></div><div><strong>One test is a snapshot, not the whole story.</strong><span>Focus on your patterns, notice what is getting easier, and keep practicing.</span></div><div className="mock-total"><strong>{mocks.length}</strong><small>check-ins</small></div></div><div className="card mock-table-card"><div className="section-head"><div><div className="section-kicker">YOUR CHECK-INS</div><h3>Practice results</h3></div><span className="result-count">{mocks.length} {mocks.length===1?'result':'results'}</span></div>{mocks.length?<><div className="mock-table-head"><span>TEST &amp; DATE</span><span>LISTENING</span><span>READING</span><span>WRITING</span><span>SPEAKING</span><span>OVERALL</span></div>{mocks.map(m=>{const nums=[m.listening,m.reading,m.writing,m.speaking].map(Number);const overall=nums.every(v=>v>0)?String(Math.round((nums.reduce((a,n)=>a+n,0)/4)*2)/2):'—';return <div className="mock-table-row" key={m.id}><div className="mock-test-name"><span className="mock-row-icon"><FileText size={16}/></span><span><strong>{m.label}</strong><small>{m.date}{m.label.includes('illustrative')?' · sample data':''}</small></span></div>{([['listening','orange'],['reading','blue'],['writing','purple'],['speaking','green']] as const).map(([s,c])=><span key={s} className="mock-band"><i className={c}/>{m[s]}</span>)}<strong className="overall-band">{overall}</strong></div>})}</>:<div className="empty-state"><span className="empty-state-icon"><ClipboardCheck size={21}/></span><strong>Your first practice result goes here.</strong><p>Enter results from a diagnostic or practice test to start building your record.</p><Button variant="secondary" onClick={onAdd} icon={<Plus size={15}/>}>Log your first result</Button></div>}<div className="mock-legend"><span><i className="illustrative-dot"/> All scores are illustrative examples</span><button onClick={onAdd}>Add another result <ArrowRight size={13}/></button></div></div><div className="gentle-note"><span className="gentle-note-icon"><Sparkles size={17}/></span><p><strong>About overall bands:</strong> When all four skill scores are provided, the displayed overall band is calculated from their average and rounded to the nearest half band.</p></div></>}
function StudyMaterials({pdfs,onUpload,onOpen,onRemove,onRetrySync,onInstall,canInstall}:{pdfs:PdfDocument[];onUpload:(files:FileList|File[])=>void;onOpen:(pdf:PdfDocument)=>void;onRemove:(pdf:PdfDocument)=>void;onRetrySync:(pdf:PdfDocument)=>void;onInstall:()=>void;canInstall:boolean}){const [showHelp,setShowHelp]=useState(false);const [dragging,setDragging]=useState(false);const inputId='study-pdf-upload';return <><Heading eyebrow="YOUR PERSONAL TEST LIBRARY" title={<>Practice wherever <em>life takes you.</em></>} sub="Add your IELTS practice PDFs once, then open or download them whenever you study." right={<Button icon={<Upload size={15}/>} onClick={()=>document.getElementById(inputId)?.click()}>Add test PDFs</Button>}/><label className={`pdf-upload-zone ${dragging?'pdf-upload-dragging':''}`} htmlFor={inputId} onDragOver={e=>{e.preventDefault();setDragging(true)}} onDragLeave={()=>setDragging(false)} onDrop={e=>{e.preventDefault();setDragging(false);onUpload(e.dataTransfer.files)}}><span className="pdf-upload-icon"><Upload size={21}/></span><strong>Bring your practice papers together</strong><span>Choose IELTS test PDFs from your device, or drag them here. Sync saved PDFs to your account to open them on your other devices.</span><small>PDF only · up to 25 MB per file · select several at once</small><input id={inputId} type="file" accept="application/pdf,.pdf" multiple onChange={e=>{if(e.currentTarget.files)onUpload(e.currentTarget.files);e.currentTarget.value=''}}/></label><section className="card pdf-library-card"><div className="section-head"><div><div className="section-kicker">YOUR REFERENCE SHELF</div><h3>My practice PDFs <span className="soft-count">{pdfs.length}</span></h3></div><span className="plan-status"><span/>{pdfs.some(pdf=>pdf.cloudSynced)?'Synced to your account':pdfs.length?'Saved on this device':'Ready for your first test'}</span></div>{pdfs.length?<div className="pdf-library-list">{pdfs.map(pdf=><article className="pdf-item" key={pdf.id}><span className="pdf-file-icon"><FileText size={19}/><small>PDF</small></span><span className="pdf-item-info"><strong title={pdf.name}>{pdf.name}</strong><small>{formatBytes(pdf.size)} <span>·</span> Added {new Intl.DateTimeFormat('en',{month:'short',day:'numeric'}).format(new Date(pdf.addedAt))}</small><small className={pdf.cloudSynced?'pdf-sync-copy':'pdf-sync-copy pdf-sync-needed'}>{pdf.cloudSynced?'✓ Synced to your account':'This device only ·'}{!pdf.cloudSynced&&<button onClick={()=>onRetrySync(pdf)}>Sync across devices</button>}</small></span><button className="pdf-open-button" onClick={()=>onOpen(pdf)}><BookOpen size={15}/><span>Open</span></button><button className="pdf-download-button" onClick={()=>onOpen(pdf)} aria-label={`Open ${pdf.name} to download`}><Download size={17}/></button><button className="pdf-remove-button" onClick={()=>onRemove(pdf)} aria-label={`Remove ${pdf.name}`}><Trash2 size={16}/></button></article>)}</div>:<div className="pdf-empty-state"><span className="pdf-empty-icon"><BookOpen size={21}/></span><div><strong>Your next practice test can start right here.</strong><p>Upload PDF question papers, answer sheets or study guides you already have access to. Open a paper to read it and download a copy for your phone or tablet.</p><Button variant="secondary" icon={<Plus size={15}/>} onClick={()=>document.getElementById(inputId)?.click()}>Choose a practice PDF</Button></div></div>}</section><section className="card install-card"><span className="install-phone"><Download size={19}/><span>✓</span></span><div><div className="section-kicker">A STUDY SPACE THAT TRAVELS</div><strong>Take your prep with you</strong><p>Install Fluent as an app on your phone. Sign in on your laptop or phone to access synced progress and PDFs.</p>{showHelp&&<div className="install-help"><strong>On iPhone or iPad</strong><span>Open this page in Safari, tap Share, then choose “Add to Home Screen.”</span><strong>On Android</strong><span>Open this page in Chrome and choose “Install app” from the menu.</span></div>}</div><div className="install-actions">{canInstall?<Button onClick={onInstall} icon={<Download size={15}/>}>Install app</Button>:<Button variant="secondary" onClick={()=>setShowHelp(!showHelp)}>{showHelp?'Hide install steps':'See install steps'}</Button>}</div></section><div className="privacy-note"><CheckCircle/><span>Your account data and synced PDFs are private to your login. PDFs that have not been synced stay on this device.</span></div></>}
function formatBytes(bytes:number){return bytes<1024*1024?`${Math.max(1,Math.round(bytes/1024))} KB`:`${(bytes/(1024*1024)).toFixed(1)} MB`}

function Alerts({data,streak,installPrompt,onTime,onToggleReminder,onInstall}:{data:State;streak:number;installPrompt:boolean;onTime:(time:string)=>void;onToggleReminder:(enabled:boolean)=>void;onInstall:()=>void}){const [showInstallHelp,setShowInstallHelp]=useState(false);const weekCount=recentStudyDays(data.studyDates);const unfinished=data.tasks.filter(task=>!task.done);return <><Heading eyebrow="YOUR GENTLE NUDGE CENTER" title={<>A little support, <em>right on time.</em></>} sub="See your progress, set a daily nudge and choose how you’d like to study."/><section className="streak-feature"><div className="streak-feature-top"><span className="streak-feature-symbol"><Flame size={24}/></span><span className="streak-live-pill"><i/> YOUR CURRENT STREAK</span><span className="streak-best"><Trophy size={14}/> Your study journey</span></div><div className="streak-count"><strong>{streak}</strong><span>{streak===1?'day':'days'}</span></div><p>{streak>0?'Every session you complete is a reason to feel proud. Come back tomorrow to keep the rhythm going.':'Pick one small session today and start your streak.'}</p><div className="streak-week-dots">{Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));const active=data.studyDates.includes(dayKey(d));return <div className="streak-day" key={dayKey(d)}><span className={active?'active':''}>{active?<Check size={14}/>:<span/>}</span><small>{new Intl.DateTimeFormat('en',{weekday:'narrow'}).format(d)}</small></div>})}</div><div className="streak-feature-footer"><span>{weekCount} study {weekCount===1?'day':'days'} this week</span><span>Steady effort beats perfect days.</span></div></section><div className="alerts-grid"><section className="card reminder-card"><span className="reminder-icon"><AlarmClock size={19}/></span><div className="section-kicker">YOUR DAILY REMINDER</div><h3>Make room for a little practice.</h3><p>Get an optional browser notification at a time that works for you. Reminders run while the app is open.</p><label className="reminder-time-field"><span>Remind me at</span><input type="time" value={data.reminderTime} onChange={e=>onTime(e.target.value)}/></label><button className={`reminder-toggle ${data.reminderEnabled?'reminder-toggle-on':''}`} aria-pressed={data.reminderEnabled} onClick={()=>onToggleReminder(!data.reminderEnabled)}><span className="toggle-track"><i/></span><span>{data.reminderEnabled?`Reminder on · ${data.reminderTime}`:'Turn on daily reminders'}</span><ArrowRight size={14}/></button><span className="reminder-disclaimer">Your browser asks for notification permission when you turn this on.</span></section><section className="card alerts-list-card"><div className="section-head"><div><div className="section-kicker">A FRIENDLY CHECK-IN</div><h3>Your study alerts</h3></div><Bell size={17} className="alerts-heading-icon"/></div><div className="alert-feed-item"><span className="alert-feed-icon amber"><Flame size={16}/></span><span><strong>{streak>0?`${streak}-day streak`: 'Your next streak starts today'}</strong><small>Complete any session to keep your learning moving.</small></span></div><div className="alert-feed-item"><span className="alert-feed-icon sage"><CalendarDays size={16}/></span><span><strong>{unfinished.length?`${unfinished.length} sessions on your plan today`:'You’re all caught up for today'}</strong><small>{unfinished.length?'Pick whichever one fits your energy and time.':'Nice work finishing your planned sessions.'}</small></span></div><div className="alert-feed-item"><span className="alert-feed-icon blue"><Target size={16}/></span><span><strong>{data.profile.examDate?'Your exam plan is on track':'Set your exam date when you’re ready'}</strong><small>{data.profile.examDate?`Exam date: ${new Intl.DateTimeFormat('en',{month:'short',day:'numeric',year:'numeric'}).format(new Date(`${data.profile.examDate}T00:00:00`))}`:'Your 12-week study plan works even before you book.'}</small></span></div></section></div><section className="card mobile-install-card"><span className="install-phone"><Download size={19}/><span>✓</span></span><span className="mobile-install-copy"><span className="section-kicker">STUDY ON YOUR PHONE</span><strong>Install Fluent for mobile</strong><small>The full study workspace works on your phone and tablet.</small></span>{installPrompt?<Button onClick={onInstall} icon={<Download size={14}/>}>Install</Button>:<Button variant="secondary" onClick={()=>setShowInstallHelp(!showInstallHelp)}>{showInstallHelp?'Hide':'How to install'}</Button>}</section>{showInstallHelp&&<div className="install-help inline-install-help"><strong>iPhone or iPad</strong><span>In Safari, tap Share and choose “Add to Home Screen.”</span><strong>Android</strong><span>In Chrome, open the menu and choose “Install app.”</span></div>}<div className="gentle-note"><span className="gentle-note-icon"><Sparkles size={17}/></span><p><strong>Your pace is your own.</strong> Streaks celebrate consistency; they’re here to encourage you, never to make a missed day feel like a setback.</p></div></>}

function Modal({modal,isOnboarding,profile,setProfile,onClose,onSaveProfile,onAddMistake,onAddMock,onAddTask,onDiagnostic}:{modal:'profile'|'mistake'|'mock'|'diagnostic'|'task';isOnboarding:boolean;profile:Profile;setProfile:(p:Profile)=>void;onClose:()=>void;onSaveProfile:(e:React.FormEvent)=>void;onAddMistake:(e:React.FormEvent<HTMLFormElement>)=>void;onAddMock:(e:React.FormEvent<HTMLFormElement>)=>void;onAddTask:(title:string,skill:string,duration:number)=>void;onDiagnostic:(skill:string)=>void}){
 const titles={profile:isOnboarding?'Welcome to Fluent':'Your study profile',mistake:'A learning moment',mock:'Log a practice test',diagnostic:'Start with a skills check',task:'Make time for a session'};const subtitles={profile:isOnboarding?'Let’s shape a starting plan around you. You can change anything later.':'Your plan should fit your life. Change the details any time.',mistake:'Every mistake is information. Save what you learned.',mock:'Add your scores when you finish a full test or a single skill.',diagnostic:'Choose a skill to create a check-in in your practice log.',task:'Make this study routine work for you.'};const [taskTitle,setTaskTitle]=useState('Vocabulary review');const [taskSkill,setTaskSkill]=useState('Review');const [duration,setDuration]=useState(30);return <div className="modal-backdrop" onClick={onClose}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" onClick={e=>e.stopPropagation()}><button className="modal-close icon-button" onClick={onClose} aria-label="Close"><X size={19}/></button><span className="modal-spark"><Sparkles size={19}/></span><h2 id="modal-title">{titles[modal]}</h2><p className="modal-subtitle">{subtitles[modal]}</p>
 {modal==='profile'&&<form className="modal-form" onSubmit={onSaveProfile}><label>Your name<input value={profile.name} onChange={e=>setProfile({...profile,name:e.target.value})} required/></label><div className="form-row"><label>IELTS type<select value={profile.exam} onChange={e=>setProfile({...profile,exam:e.target.value})}><option>Academic</option><option>General Training</option></select></label><label>Current level<select value={profile.level} onChange={e=>setProfile({...profile,level:e.target.value})}><option>Beginner</option><option>Elementary</option><option>Intermediate</option><option>Upper intermediate</option><option>Advanced</option></select></label></div><div className="form-row"><label>Target band<select value={profile.target} onChange={e=>setProfile({...profile,target:Number(e.target.value)})}>{[6,6.5,7,7.5,8,8.5,9].map(v=><option key={v} value={v}>{v.toFixed(1)}</option>)}</select></label><label>Study hours / day<input type="number" min="1" max="12" value={profile.hours} onChange={e=>setProfile({...profile,hours:Number(e.target.value)})}/></label></div><div className="form-row"><label>Timeline (weeks)<input type="number" min="1" max="52" value={profile.weeks} onChange={e=>setProfile({...profile,weeks:Number(e.target.value)})}/></label><label>Exam date <span className="optional-label">optional</span><input type="date" value={profile.examDate} onChange={e=>setProfile({...profile,examDate:e.target.value})}/></label></div><div className="modal-buttons"><Button variant="secondary" onClick={onClose}>Cancel</Button><Button icon={<Check size={15}/>}>{isOnboarding?'Start my study plan':'Save profile'}</Button></div></form>}
 {modal==='mistake'&&<form className="modal-form" onSubmit={onAddMistake}><label>What was tricky?<input name="title" placeholder="e.g. Matching headings" required/></label><div className="form-row"><label>IELTS skill<select name="skill">{['Listening','Reading','Writing','Speaking'].map(s=><option key={s}>{s}</option>)}</select></label><label>Type of note<select name="category">{['Grammar','Vocabulary','Spelling','Strategy','Timing','Pronunciation','Other'].map(s=><option key={s}>{s}</option>)}</select></label></div><label>What did you learn?<textarea name="detail" rows={4} placeholder="Write down what happened and what you’ll try next time…" required/></label><div className="modal-buttons"><Button variant="secondary" onClick={onClose}>Cancel</Button><Button icon={<Plus size={15}/>}>Save learning moment</Button></div></form>}
 {modal==='mock'&&<form className="modal-form" onSubmit={onAddMock}><label>Test name<input name="label" placeholder="e.g. Cambridge practice test 1" defaultValue="Practice test" required/></label><div className="form-row"><label>Date<input name="date" type="date" defaultValue={new Date().toISOString().slice(0,10)}/></label><label>Listening <span className="optional-label">band · optional</span><input name="listening" type="number" min="0.5" max="9" step="0.5" placeholder="0 – 9"/></label></div><div className="form-row"><label>Reading <span className="optional-label">band · optional</span><input name="reading" type="number" min="0.5" max="9" step="0.5" placeholder="0 – 9"/></label><label>Writing <span className="optional-label">band · optional</span><input name="writing" type="number" min="0.5" max="9" step="0.5" placeholder="0 – 9"/></label></div><div className="form-row"><label>Speaking <span className="optional-label">band · optional</span><input name="speaking" type="number" min="0.5" max="9" step="0.5" placeholder="0 – 9"/></label><div className="field-tip"><Sparkles size={14}/> Only enter scores you’ve received so far.</div></div><div className="modal-buttons"><Button variant="secondary" onClick={onClose}>Cancel</Button><Button icon={<Check size={15}/>}>Save results</Button></div></form>}
 {modal==='diagnostic'&&<div className="diagnostic-choices"><p>Pick a skill to log a starting-point check-in. You can add or update its result afterward.</p>{(['Listening','Reading','Writing','Speaking'] as const).map(s=>{const Icon=icons[s];return <button key={s} onClick={()=>onDiagnostic(s)}><span className="diagnostic-skill-icon" style={{'--skill-color':skillColors[s]} as React.CSSProperties}><Icon size={18}/></span><span><strong>{s}</strong><small>Suggested starter assessment</small></span><ArrowRight size={16}/></button>})}</div>}
 {modal==='task'&&<form className="modal-form" onSubmit={e=>{e.preventDefault();onAddTask(taskTitle,taskSkill,duration)}}><label>Session title<input value={taskTitle} onChange={e=>setTaskTitle(e.target.value)} required/></label><div className="form-row"><label>IELTS skill<select value={taskSkill} onChange={e=>setTaskSkill(e.target.value)}>{['Listening','Reading','Writing','Speaking','Review'].map(s=><option key={s}>{s}</option>)}</select></label><label>Duration (minutes)<input type="number" min="5" max="240" step="5" value={duration} onChange={e=>setDuration(Number(e.target.value))}/></label></div><div className="field-tip"><Sparkles size={14}/> Your schedule can change as often as you need it to.</div><div className="modal-buttons"><Button variant="secondary" onClick={onClose}>Cancel</Button><Button icon={<Plus size={15}/>}>Add to today</Button></div></form>}
 </section></div>}
